fn yarra(arr: &Vec<char>) -> Vec<char> {
    let n = arr.len();
    let mut outarr = Vec::with_capacity(n);
    for i in 0..n {
        // Push elements from the end of `arr` to the beginning of `outarr`
        outarr.push(arr[n - 1 - i]);
    }
    outarr
}

